async function postReview(body, event) {
    if (!githubConfig.pullRequestNumber) {
        throw Error('This function can only be run on a pull request.');
    }
    const params = {
        owner: githubConfig.owner,
        repo: githubConfig.reponame,
        pull_number: githubConfig.pullRequestNumber,
        event: event,
        body: body
    };
    try {
        logger_logger.header('Posting a review for this pull request.');
        await octokit.rest.pulls.createReview(params);
        logger_logger.info('Posted review for this pull request.');
    }
    catch (error) {
        const message = handleOctokitError(error);
        logger_logger.notice(`Posting the review failed: ${message}`);
    }
}

