/**
 * Sends a request to retrieve the changed files for a given pull request to the GitHub API.
 * @returns List of changed files within the GitHub Pull request.
 */
async function getChangedFilesOfCommit() {
    const params = {
        owner: githubConfig.owner,
        repo: githubConfig.reponame,
        ref: githubConfig.sha,
        per_page: githubConfig.itemsPerPage
    };
    try {
        logger_logger.header('Retrieving changed files.');
        const response = await octokit.paginate(octokit.rest.repos.getCommit, params, resp => {
            const data = resp.data;
            return data.files ?? [];
        });
        const changedFiles = response
            // If excludeMovedFiles, filter out moved files (a file is moved if the status is 'renamed')
            .filter(item => item.changes > 0 && !(actionConfig.excludeMovedFiles && item.status === 'renamed'))
            .map(item => (0,canonical_path.normalize)(item.filename));
        logger_logger.info('Retrieved changed files from commit.');
        logger_logger.debug(JSON.stringify(changedFiles));
        return changedFiles;
    }
    catch (error) {
        const message = handleOctokitError(error);
        throw Error(`Could not retrieve the changed files: ${message}`, { cause: error });
    }
}

